INSERT INTO shared_export (recipient_org, payload, created_at) 
VALUES (
  'Office of Compliance - External Audit',
  json_group_array(
    json_object(
      'export_type', 'audit_combined_package',
      'export_date', datetime('now', 'localtime'),
      'export_description', 'Combined protocol revisions and lab contacts for external audit',
      'protocol_revisions', (
        SELECT json_array(
          json_each.value
        ) FROM json_each(
          json_group_array(
            json_object(
              'revision_id', revision_id,
              'author', author,
              'date', date,
              'content', content,
              'notes', notes
            )
          )
        )
      ),
      'lab_contacts', (
        SELECT json_array(
          json_each.value
        ) FROM json_each(
          json_group_array(
            json_object(
              'contact_id', contact_id,
              'full_name', full_name,
              'email', email,
              'role', role
            )
          )
        )
      )
    )
  ),
  datetime('now', 'localtime')
);

SELECT json_serialize(json_group_array(
  json_object(
    'revision_id', revision_id,
    'author', author,
    'date', date,
    'content', content,
    'notes', notes
  )
)
FROM protocol_revisions
);

WITH proto_data AS (
  SELECT json_group_array(
    json_object(
      'revision_id', revision_id || '-',
      'author', author,
      'date', date,
      'content', content,
      'notes', notes
    )
  ) AS proto_json
  FROM protocol_revisions
)
SELECT proto_json FROM proto_data;

